#!/usr/bin/env bash
set -euo pipefail
OUTDIR=${1:-/tmp/twv04}
mkdir -p "$OUTDIR"
FONT=/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf
BOLD=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf
BG=0x0F172A
NAVY=0x0B2A4A
SLATE=0x1E293B
MID=0x64748B
SILVER=0x98A3A8
LIGHT=0xE2E8F0
