brand="drawtext=fontfile=${BOLD}:text='TRACEWARDEN®':fontcolor=0x98A3A8:fontsize=22:x=60:y=48"
mk(){ n=$1; d=$2; vf=$3; ffmpeg -hide_banner -loglevel error -y -f lavfi -i "color=c=${BG}:s=1920x1080:r=30:d=${d}" -vf "$vf" -c:v libx264 -preset veryfast -crf 21 -pix_fmt yuv420p -t "$d" "$OUTDIR/s${n}.mp4"; }
