mk 5 14.0 "$brand,drawtext=fontfile=${BOLD}:text='NAIC · evaluación del uso de IA':fontcolor=${WHITE}:fontsize=48:x=(w-text_w)/2:y=170,drawtext=fontfile=${FONT}:text='Herramientas regulatorias en desarrollo para examinar cómo se usa y gobierna la IA en aseguradoras.':fontcolor=${LIGHT}:fontsize=26:x=(w-text_w)/2:y=275,drawbox=x=245:y=570:w=220:h=90:color=${NAVY}:t=fill,drawbox=x=245:y=570:w=220:h=90:color=${MID}:t=2,drawtext=fontfile=${BOLD}:text='USO':fontcolor=${WHITE}:fontsize=24:x=330:y=601,drawbox=x=505:y=570:w=255:h=90:color=${NAVY}:t=fill,drawbox=x=505:y=570:w=255:h=90:color=${MID}:t=2,drawtext=fontfile=${BOLD}:text='GOBERNANZA':fontcolor=${WHITE}:fontsize=22:x=550:y=601,drawbox=x=800:y=570:w=220:h=90:color=${SLATE}:t=fill,drawbox=x=800:y=570:w=220:h=90:color=${MID}:t=2,drawtext=fontfile=${BOLD}:text='RIESGOS':fontcolor=${WHITE}:fontsize=23:x=854:y=601,drawbox=x=1060:y=570:w=220:h=90:color=${SLATE}:t=fill,drawbox=x=1060:y=570:w=220:h=90:color=${MID}:t=2,drawtext=fontfile=${BOLD}:text='MODELOS':fontcolor=${WHITE}:fontsize=23:x=1110:y=601,drawbox=x=1320:y=570:w=220:h=90:color=${SLATE}:t=fill,drawbox=x=1320:y=570:w=220:h=90:color=${MID}:t=2,drawtext=fontfile=${BOLD}:text='DATOS':fontcolor=${WHITE}:fontsize=23:x=1391:y=601,drawtext=fontfile=${FONT}:text='Fuente — NAIC · Artificial Intelligence / AI Systems Evaluation Tool — 2026':fontcolor=${SILVER}:fontsize=20:x=(w-text_w)/2:y=820"
mk 6 13.0 "$brand,drawtext=fontfile=${BOLD}:text='Unión Europea · transparencia':fontcolor=${WHITE}:fontsize=48:x=(w-text_w)/2:y=170,drawtext=fontfile=${BOLD}:text='Artículo 50 de la Ley de IA':fontcolor=${LIGHT}:fontsize=39:x=(w-text_w)/2:y=330,drawtext=fontfile=${FONT}:text='Desde el 2 de agosto de 2026 comenzaron a aplicarse obligaciones específicas de':fontcolor=${LIGHT}:fontsize=25:x=(w-text_w)/2:y=455,drawtext=fontfile=${FONT}:text='transparencia para determinados sistemas y contenidos.':fontcolor=${LIGHT}:fontsize=25:x=(w-text_w)/2:y=496,drawbox=x=585:y=670:w=750:h=100:color=${NAVY}:t=fill,drawbox=x=585:y=670:w=750:h=100:color=${MID}:t=2,drawtext=fontfile=${BOLD}:text='Aplicación específica, no absoluta':fontcolor=${WHITE}:fontsize=28:x=(w-text_w)/2:y=703"
mk 7 12.5 "$brand,drawtext=fontfile=${BOLD}:text='Reconstruir · Explicar · Demostrar':fontcolor=${WHITE}:fontsize=48:x=(w-text_w)/2:y=160,drawbox=x=190:y=465:w=280:h=110:color=${NAVY}:t=fill,drawbox=x=190:y=465:w=280:h=110:color=${MID}:t=2,drawtext=fontfile=${BOLD}:text='DATOS':fontcolor=${WHITE}:fontsize=24:x=289:y=505,drawtext=fontfile=${FONT}:text='→':fontcolor=${SILVER}:fontsize=50:x=482:y=487,drawbox=x=560:y=465:w=300:h=110:color=${SLATE}:t=fill,drawbox=x=560:y=465:w=300:h=110:color=${MID}:t=2,drawtext=fontfile=${BOLD}:text='CONTROLES':fontcolor=${WHITE}:fontsize=23:x=630:y=505,drawtext=fontfile=${FONT}:text='→':fontcolor=${SILVER}:fontsize=50:x=872:y=487,drawbox=x=950:y=465:w=300:h=110:color=${SLATE}:t=fill,drawbox=x=950:y=465:w=300:h=110:color=${MID}:t=2,drawtext=fontfile=${BOLD}:text='VALIDACIÓN':fontcolor=${WHITE}:fontsize=23:x=1012:y=505,drawtext=fontfile=${FONT}:text='→':fontcolor=${SILVER}:fontsize=50:x=1262:y=487,drawbox=x=1340:y=465:w=300:h=110:color=${NAVY}:t=fill,drawbox=x=1340:y=465:w=300:h=110:color=${MID}:t=2,drawtext=fontfile=${BOLD}:text='DECISIÓN':fontcolor=${WHITE}:fontsize=23:x=1412:y=505,drawtext=fontfile=${BOLD}:text='DECISIÓN DEFENDIBLE':fontcolor=${WHITE}:fontsize=58:x=(w-text_w)/2:y=740"
ffmpeg -hide_banner -loglevel error -y -f lavfi -i "color=c=${NAVY}:s=1920x1080:r=30:d=6.5" -vf "drawtext=fontfile=${BOLD}:text='Tracewarden®':fontcolor=${WHITE}:fontsize=72:x=(w-text_w)/2:y=390,drawtext=fontfile=${FONT}:text='hace visible el riesgo que su empresa todavía no sabe que tiene.':fontcolor=${LIGHT}:fontsize=34:x=(w-text_w)/2:y=520,drawtext=fontfile=${FONT}:text='Producción audiovisual asistida por IA · Investigación y validación editorial humana':fontcolor=${SILVER}:fontsize=18:x=(w-text_w)/2:y=875" -c:v libx264 -preset veryfast -crf 21 -pix_fmt yuv420p -t 6.5 "$OUTDIR/s8.mp4"
printf "file '%s/s1.mp4'\nfile '%s/s2.mp4'\nfile '%s/s3.mp4'\nfile '%s/s4.mp4'\nfile '%s/s5.mp4'\nfile '%s/s6.mp4'\nfile '%s/s7.mp4'\nfile '%s/s8.mp4'\n" "$OUTDIR" "$OUTDIR" "$OUTDIR" "$OUTDIR" "$OUTDIR" "$OUTDIR" "$OUTDIR" "$OUTDIR" > "$OUTDIR/list.txt"
ffmpeg -hide_banner -loglevel error -y -f concat -safe 0 -i "$OUTDIR/list.txt" -c copy "$OUTDIR/visual.mp4"
